block = "\n// Дополнительные известные места: без выдуманных live-цен. Проверено редакцией 2026-11-06.\n" + "const VALUTKIN_PLACE_EXTRAS={\n" + "\n".join(f'{code}:"{names}",' for code,names in extras.items()) + "\n};\nObject.entries(VALUTKIN_PLACE_EXTRAS).forEach(([code,names])=>{const row=window.VALUTKIN_TRAVEL_GUIDE[code];if(!row)return;names.split(\"|\").forEach((name,index)=>row.places.push([name,index%3===0?\"история\":index%3===1?\"природа\":\"культура\",index<3?9:8,0]));});\n"
if "VALUTKIN_PLACE_EXTRAS" not in text:
    path.write_text(text + block)
